import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 로그인 구분 허용값
const LOGIN_TYPES = ['웹', '메신저', '모바일 앱'];
// 가정: 임직원 한 명이 로그인에 쓸 수 있는 승인·사용 기기의 최대 수
const MAX_DEVICES = 5;
// 가정: OTP는 숫자 6자리
const OTP_PATTERN = /^[0-9]{6}$/;

interface EmployeeRow {
  employeeId: number;
  employmentStatus: string;
  twoFactorRequired: boolean | null;
  passwordOk: boolean | null;
}

interface DeviceRow {
  deviceIdentifier: string;
  otpEnabled: boolean;
}

function text(value: unknown, name: string, max?: number): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값을 입력해 주세요.');
  }
  if (max !== undefined && value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 너무 깁니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr03701Controller {
  @Post('/auth/login')
  @HttpCode(200)
  async login(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const loginType = text(data['loginType'], '로그인 구분');
    if (!LOGIN_TYPES.includes(loginType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '로그인 구분은 웹, 메신저, 모바일 앱 중 하나여야 합니다.');
    }
    const userId = text(data['userId'], '사번', 50);
    const password = text(data['password'], '비밀번호');
    const deviceIdentifier = text(data['deviceIdentifier'], '기기 식별정보', 200);
    const otpRaw = data['otpValue'];
    if (otpRaw !== undefined && otpRaw !== null && typeof otpRaw !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', 'OTP 값 형식이 올바르지 않습니다.');
    }
    const otpValue = typeof otpRaw === 'string' ? otpRaw.trim() : '';

    return transaction(async (db) => {
      // 1차 인증. 가정: password_hash는 pgcrypto crypt() 형식의 해시이므로 DB에서 비교한다.
      const employees = (await db.query(
        `SELECT employee_id AS "employeeId",
                employment_status AS "employmentStatus",
                two_factor_required AS "twoFactorRequired",
                (password_hash IS NOT NULL AND password_hash = crypt(CAST(:password AS text), password_hash)) AS "passwordOk"
           FROM employee
          WHERE employee_no = :userId`,
        { userId, password },
      )) as EmployeeRow[];
      const employee = employees[0];
      if (!employee || employee.passwordOk !== true || employee.employmentStatus !== '재직자') {
        throw new ApiError(422, 'INVALID_CREDENTIALS', '사번 또는 비밀번호가 일치하지 않습니다.');
      }

      // 가정: 2차 인증 대상(two_factor_required = true)만 기기 승인과 OTP를 확인하고, 그 밖의 사용자는 생략한다.
      if (employee.twoFactorRequired === true) {
        const devices = (await db.query(
          `SELECT device_identifier AS "deviceIdentifier",
                  otp_enabled AS "otpEnabled"
             FROM auth_device
            WHERE employee_id = CAST(:employeeId AS bigint)
              AND approval_status = '승인'
              AND use_status = '사용'`,
          { employeeId: employee.employeeId },
        )) as DeviceRow[];
        const allowed = devices.some((d) => d.deviceIdentifier === deviceIdentifier && d.otpEnabled === true);
        if (!allowed || devices.length > MAX_DEVICES) {
          throw new ApiError(422, 'AUTH_DEVICE_NOT_ALLOWED', '사용할 수 없는 인증기기입니다. 기기 승인을 요청하거나 관리자에게 문의해 주세요.');
        }
        if (!OTP_PATTERN.test(otpValue)) {
          throw new ApiError(422, 'INVALID_OTP', 'OTP가 유효하지 않거나 만료되었습니다.');
        }
        // TODO: OTP 값을 실제로 검증할 저장소·방식이 입력에 없어 형식만 확인한다.
      }

      // 가정: 토큰은 인증 성공 시 DB에서 난수로 발급한다.
      const tokens = (await db.query(
        `SELECT encode(gen_random_bytes(32), 'hex') AS "accessToken"`,
        {},
      )) as Array<{ accessToken: string }>;
      return {
        accessToken: tokens[0].accessToken,
        employeeId: employee.employeeId,
      };
    });
  }
}

