import { useState } from 'react';
import { Band, DataTable, DateText, Drawer, Field, Form, RefName, Select, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

const LOGIN_TYPES: [string, string][] = [
  ['웹', '웹'],
  ['메신저', '메신저'],
  ['모바일 앱', '모바일 앱'],
];

function isBlank(value: unknown): boolean {
  return value === undefined || value === null || String(value).trim() === '';
}

export default function FnSfr03701Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [results, setResults] = useState<Row[]>([]);
  const [loginType, setLoginType] = useState('');
  const [userId, setUserId] = useState('');
  const [password, setPassword] = useState('');
  const [otpValue, setOtpValue] = useState('');
  const [deviceIdentifier, setDeviceIdentifier] = useState('');

  function openDrawer() {
    setLoginType('');
    setUserId('');
    setPassword('');
    setOtpValue('');
    setDeviceIdentifier('');
    setOpen(true);
  }

  async function submit() {
    if (isBlank(loginType)) throw new Error('로그인 구분을 선택해 주세요.');
    if (isBlank(userId)) throw new Error('사번을 입력해 주세요.');
    if (isBlank(password)) throw new Error('비밀번호를 입력해 주세요.');
    if (isBlank(deviceIdentifier)) throw new Error('기기 식별정보를 입력해 주세요.');
    const body: Row = { loginType, userId, password, deviceIdentifier };
    if (!isBlank(otpValue)) body.otpValue = otpValue;
    const res = await call('POST', '/auth/login', role, body);
    setPassword('');
    setResults([
      { employeeId: res.employeeId, loginType, userId, at: new Date().toISOString() },
      ...results,
    ]);
    setOpen(false);
    notify('로그인했습니다.');
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>2차 인증 로그인</h2>
        <Band total={results.length}>
          <button onClick={openDrawer}>로그인</button>
        </Band>
        <DataTable
          columns={[
            { key: 'at', label: '로그인 일시', render: (r) => <DateText value={r.at} time /> },
            { key: 'loginType', label: '로그인 구분' },
            { key: 'userId', label: '사번' },
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
          ]}
          rows={results}
          empty="아직 로그인한 내역이 없습니다. 로그인 버튼을 눌러 시작해 주세요."
        />
      </section>
      {open && (
        <Drawer title="로그인" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="로그인"
            note="1차 인증과 2차 인증이 모두 성공해야 로그인이 완료됩니다. 2차 인증 대상이 아니면 OTP는 비워 둘 수 있습니다."
          >
            <Field label="웹/메신저/모바일 앱" required>
              <Select value={loginType} onChange={setLoginType} options={LOGIN_TYPES} />
            </Field>
            <Field label="사번" required>
              <TextInput value={userId} onChange={setUserId} />
            </Field>
            <Field label="1차 인증용 비밀번호" required>
              <TextInput value={password} onChange={setPassword} />
            </Field>
            <Field label="OTP 일회용 값">
              <TextInput value={otpValue} onChange={setOtpValue} />
            </Field>
            <Field label="기기 식별정보" required>
              <TextInput value={deviceIdentifier} onChange={setDeviceIdentifier} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
